effect.shader:
vec2 clampMirror(vec2 uv){
  if(mirrorEdge){
    uv = vec2(1.0,1.0) - abs(mod(uv,vec2(2.0,2.0)) - vec2(1.0,1.0));
  } else {
    uv = clamp(uv, vec2(0.0), vec2(1.0));
  }
  return uv;
}
vec4 sample(vec2 uv){ return texture2DCv(inputImg.texture, clampMirror(uv)); }

// Half-tap budget. Beyond 64 half-taps (129 samples) adjacent samples land
// sub-pixel apart on any sane radius, so we hold the tap count and widen the
// stride instead: extent = halfTaps*stride = radius, unchanged.
// Extent is clamped to 1024 px exactly as the original loop bound did.
highp float blurExtent(float radiusPx){ return min(1024.0, max(1.0, floor(radiusPx))); }

vec4 blurBox(vec2 uv, float radiusPx){
  if(radiusPx<=0.0) return sample(uv);
  highp float texY = 1.0/getTexSize(inputImg.size).y;
  highp float r = blurExtent(radiusPx);
  highp float n = min(r, 64.0);          // half-taps actually taken
  highp float du = (r/n)*texY;           // stride in UV; n*du == r px
  mediump vec4 acc = sample(uv);
  highp float w = 1.0;
  for(int i=1;i<=64;i++){
    if(float(i)>n) break;
    highp float o = float(i)*du;
    acc += sample(uv+vec2(0.0,o)) + sample(uv-vec2(0.0,o));
    w += 2.0;
  }
  return acc/max(1.0,w);
}
vec4 blurGaussian(vec2 uv, float radiusPx){
  if(radiusPx<=0.0) return sample(uv);
  highp float texY = 1.0/getTexSize(inputImg.size).y;
  highp float r = blurExtent(radiusPx);
  highp float n = min(r, 64.0);
  highp float stride = r/n;              // pixels between taps
  highp float du = stride*texY;
  highp float sigma = max(0.0001, radiusPx*0.35);
  highp float k = -1.0/(2.0*sigma*sigma);  // hoisted out of the loop
  mediump vec4 acc = sample(uv);           // i==0, weight 1
  highp float wsum = 1.0;
  for(int i=1;i<=64;i++){
    if(float(i)>n) break;
    highp float d = float(i)*stride;       // true pixel distance
    mediump float w = exp(k*d*d);
    highp float o = float(i)*du;
    acc += (sample(uv+vec2(0.0,o)) + sample(uv-vec2(0.0,o))) * w;
    wsum += 2.0*w;
  }
  return acc/max(0.0001,wsum);
}
vec4 blurTriangle(vec2 uv, float radiusPx, int iterations){
  // Each "iteration" overwrote outC with an identical blurBox of the same
  // source and radius, so N passes == 1 pass. Collapsed to one evaluation.
  vec4 outC = sample(uv);
  if(iterations>=1) outC = blurBox(uv, radiusPx);
  return outC;
}
void main(){
  float radiusPx = yWidth * (glowRadius/100.0);
  vec2 uv = acScreenNorm;
  vec4 col;
  if(blurType==0){ col = blurTriangle(uv, radiusPx, int(triangleIterations)); }
  else if(blurType==1){ col = blurGaussian(uv, radiusPx); }
  else { col = blurBox(uv, radiusPx); }
  gl_FragColor = col;
}
